import json,re
from pathlib import Path
R=Path(__file__).resolve().parents[2]; E=R/'evidence/02'
files=[E/'notes.json',*sorted(E.glob('notes_extra*.json'))]
records={};owners={}
for f in files:
 for k,v in json.loads(f.read_text(encoding='utf-8')).items(): records[k]=v;owners[k]=f
def upd(k,**v):records[k].update(v)
upd('learning_to_map',authors='Georgios Georgakis; Bernadette Bucher; Karl Schmeckpeper; Siddharth Singh; Kostas Daniilidis')
upd('genex',title='GenEx: Generating an Explorable World',
 mechanism='Sections 3–4 adapt Stable Video Diffusion to panoramic exploration. The system first rotates the sphere geometrically, then generates a forward video segment. The spherical-consistency objective (Eq. 2) decodes generated latents, rotates predicted and target panoramas together, re-encodes them and penalizes their latent difference alongside ordinary diffusion loss. An LLM proposes orientation/distance and reasons over generated views. GenEx-DB contains four synthetic visual styles; Street View and Behavior Vision Suite provide held-out domains. Equation 4 describes belief updates using imagined observations, but a calibrated posterior-inference algorithm is not established. Generated views are samples from the model conditioned on available evidence; they are not additional camera measurements.',
 results='Table 1, p. 8: FVD is 69.5 for the full method, 81.9 without spherical consistency and 196.7 for six-view generation. IELC measures Inception-feature error after 1,000 closed imagined loops. Table 2, p. 9 gives 0.105 on street scenes and 0.092 indoors, so a blanket claim that both are below 0.1 is inaccurate. GenEx-EQA contains more than 200 synthetic scenarios and uses GPT-4o as a judge for logic scoring. These are generated-world/QA evaluations, not R2R success or physical navigation deployment.',
 novelty='The contribution combines panoramic video exploration, spherical consistency and an embodied-QA benchmark. It targets coherent imagined perspective-taking rather than a learned navigation action policy.',
 bottleneck='DEDUCTION: conditional on a fixed real history and model, self-generated samples add computation but no independent observational information about the actual hidden state. Counting them as independent likelihood evidence can create unwarranted certainty. A consistently false generated world can satisfy loop closure. Facts about an occluded physical hazard require a real observation or an explicitly justified prior.',
 followups='SALI, ImagineNav, Pathdreamer and WorldVLN differ in their interfaces between real and imagined evidence. A useful research gap concerns provenance and decision reliability, rather than the mere ability to retain or lengthen generation.')
upd('monodream',
 problem='Monocular RGB VLN-CE with eight historical frames. Panoramic RGB and depth are privileged training targets.',
 mechanism='The NVILA-lite 2B backbone (SigLIP plus Qwen2) outputs a unified state h_t. Four mean-squared-error terms (Eq. 5) align h_t-derived predictions with current and future panoramic RGB/depth features. Panoramas use four cube-map views; depth is log-scaled and colorized. The agent predicts the next three actions with cross-entropy (Eq. 6) and reconstructs the instruction with cross-entropy (Eq. 7), optimizing their weighted sum (Eq. 8). Projection and pooling dimensions are incompletely specified. Training uses five epochs on eight H20 GPUs, batch 80 and learning rate 1e-5, with 320,000 R2R steps, 600,000 RxR steps and 500,000 DAgger steps. Auxiliary heads are disabled at inference, so deployment has no imagined rollout or search. The authors\' claim of no external data concerns additional navigation fine-tuning data, not the foundation models\' pretraining.',
 novelty='Privileged geometric, panoramic and future supervision improves a monocular representation. This extends the training-supervision role seen in VLN-SIG and differs from DREAMWALKER\'s online generation.',
 results='The main R2R result is SR 55.8/SPL 49.1. RxR is 49.4/40.9 versus NaVILA 49.3/44.0, so the method does not obtain the highest SPL. Table 5, p. 7, on the smaller ablation training setting: current-depth-only SR is 42.2, future-depth-only 39.8, and the full method 46.1. Table 6 shows decreasing SR with prediction horizon: one step 39.1, two steps 34.3, three steps 29.2. Table 7 reports 0.8 seconds per step on a 4090 versus 1.2 seconds for 8B baselines, but model size differs.',
 bottleneck='Longer prediction supervision can hurt under partial observability. Current geometry/panoramic information may explain more of the gain than foresight. The model has no deployment confidence-calibration or observed-residual correction mechanism. No independently executed experiment establishes transfer beyond the reported protocol.',
 followups='FantasyVLN also uses imagination mainly during training; NavForesee retains predicted semantic/depth structures in action computation. Comparisons must match sensing, data and backbone size.')
upd('navforesee',title='NavForesee: A Unified Vision-Language World Model for Hierarchical Planning and Dual-Horizon Navigation Prediction',
 problem='RGB VLN-CE using observation history and relative pose, with hierarchical instruction planning and continuous waypoint chunks.',
 mechanism='Section 3: Qwen2.5-VL 3B predicts planning text and two sets of future queries: a fixed short horizon and a longer milestone horizon. Gemini 2.5 Pro annotates 10,000 R2R and 20,000 RxR episodes; 16.7% of poor terminal milestones are filtered, leaving about 0.2 million and 1.3 million steps. Structured attention lets long-horizon queries see short-horizon queries, separates semantic/depth branches and lets action queries see all of them. Heads predict DINO/SAM semantic features with MSE and depth with scale-invariant logarithmic loss. An inverse-dynamics head predicts K×5 waypoint vectors (x, y, sin(theta), cos(theta), stop) with MSE; planning text uses cross-entropy. These are goal-conditioned future targets and inverse action prediction, not clearly candidate-action-conditioned counterfactual simulation. New real observations refresh each control cycle, but no calibrated observed-residual objective is specified.',
 novelty='Combines hierarchical language planning with two-horizon semantic/geometric prediction. Planning-only and prediction-only controls are necessary to distinguish its contribution from HNR, NavMorph and MonoDream.',
 results='Table 1, p. 7: R2R SR 66.2/SPL 59.7 versus CorrectNav 65.1/62.3; RxR 66.3/53.2 versus 69.3/63.3. Table 2 gives 66.2/59.7 for the full system, 48.8/39.4 without VLM planning and 58.6/50.1 without long-horizon prediction. Table 3 gives short-horizon SR 66.2 at five steps, 64.1 at four and 56.5 at three. Ablations support the internal recipe, while the headline comparisons do not show uniform superiority.',
 bottleneck='Predicted futures may act as goal templates rather than faithful consequences of alternative actions. Teacher annotation and filtering add cost and data selection. Qualitative geometric fidelity does not validate confidence. No official implementation was verified.',
 followups='WorldVLN and LCVN unify action/observation prediction differently. SC²-WM adds delayed observed-residual adaptation as well as immediate internal refinement; those mechanisms must be distinguished from simple anticipation.')
upd('fantasyvln',title='FantasyVLN: Unified Multimodal Chain-of-Thought Reasoning for Vision-and-Language Navigation',
 problem='Long, multistage LH-VLN with a 7B VLM. The aim is to benefit from reasoning supervision while using a fast direct action mode at deployment.',
 mechanism='The backbone supports four gated modes: direct non-CoT, textual CoT, coarse VAR visual CoT, and combined multimodal CoT. The VAR decoder is frozen. Equations 4–8 alternate direct action cross-entropy with cross-mode alignment. After a non-CoT update, its detached action-token probabilities supervise CoT action outputs, while ordinary token losses supervise the reasoning content. Thus the explicit alignment direction is not simply a CoT teacher distilled into a direct student. Shared backbone updates may still improve the direct mode. Deployment primarily selects non-CoT inference, making visual imagination chiefly a training mechanism; the code audit below confirms the alternating update order.',
 novelty='Unified reasoning modes and action alignment provide auxiliary learning for a fast direct policy. CoT-VLA instead generates intermediate images during deployment. Auxiliary reasoning supervision and shared-backbone transfer are close prior mechanisms that constrain broad novelty claims.',
 results='Table 1, p. 6: full-task SR 2.44, ISR 11.01, CSR 9.64 and CGT 8.99, versus Aux-Think SR 0.65 and baseline SR 0. Table 2 reports 1.03 actions per second versus CoT-VLA 0.19 (about 5.4 times faster) and WorldVLA 1.02. Table 3 gives visual-only non-CoT ISR 11.19, slightly above the full system\'s 11.01, although the full system has better complete-task SR. Removing alignment gives SR 0. CoT-VLA and Aux-Think were reimplemented because their original code was unavailable, limiting direct comparability.',
 bottleneck='More than 97% of full tasks still fail. Token alignment does not prove that reasoning is faithful or causally responsible for actions; auxiliary branches may provide representation regularization. Foundation-model priors, scale and training data complicate attribution.',
 followups='MonoDream disables auxiliary heads at inference. NavForesee and WorldVLN retain predicted structures in action computation. Grouping these papers by actual deployment use is more informative than grouping by the word imagination.')
upd('worldvln',title='WorldVLN: Autoregressive World Action Model for Aerial Vision-Language Navigation',
 problem='Aerial language navigation with four-dimensional displacement/yaw waypoints. The task differs from ground-based R2R-CE.',
 mechanism='An InfinityStar latent autoregressive video model predicts the next segment from language and real observation history. A Wan VAE and TSformer visual-odometry initialization support action decoding. The system executes a segment, then replaces its imagined history with newly encoded real video (Eqs. 3–6). Stage one combines visual likelihood with action regression (Eqs. 7–8). Stage two uses online GRPO with trajectory-closeness, terminal-distance and reference-action likelihood rewards (Eqs. 9–13). Training uses eight 80 GB A800 GPUs and simulation uses a 4090. Mathematical caveat: multiplying all rewards in a per-time-step group by the same positive gamma^(j−1) cancels in standardized advantages (Eq. 13), apart from epsilon. Early-step weighting therefore needs an additional noncancelling weight or a different grouping. The continuous-action likelihood used by GRPO also requires implementation specification.',
 novelty='Integrates generated visual/action sequences, navigation reinforcement learning and periodic replacement by real history. Unlike training-only imagination, generated segments affect execution; unlike a fully observed controller, feedback is delayed until the segment ends.',
 results='Table 1 reports average SR 79.12/78.02 for fixed/open UAVFlow instructions. Table 2 gives indoor SR 41.76/nDTW 13.48 versus pi0 27.16/9.44. On the easy subset nDTW 13.04 is below pi0 14.52. These are author-reported aerial-navigation experiments, not executed reproduction or ground-navigation results.',
 bottleneck='Segmented execution delays correction. Reinforcement learning can exploit model or reward inaccuracies. The reward-scale cancellation is a scoped deduction that requires reconciliation with the unreleased trainer. The official snapshot is a project page, so actual action likelihoods, optimization and evaluation code remain unavailable.',
 followups='NWM, LCVN, CoT-VLA and Vid2World are close mechanistic comparisons. Real-observation assimilation must be separated from internal feedback computed only from predictions.')
upd('vlnsig',title='Improving Vision-and-Language Navigation by Generating Future-View Image Semantics',associated=['VLN-SIG (supplement).pdf, pp. 1–3: objectives, weighted-patch argument, hyperparameters and additional evaluations.'],
 access='Supplement p. 2 gives dynamic vocabulary size 1000, frequency/difficulty weights gamma=1 and lambda=0.5, task-mixture/masking settings, and about 30 hours on two A6000 GPUs. Its weighted-patch result assumes equality over sufficiently rich weights and a linear decomposition; it is not a finite-optimization guarantee. Supplement p. 3 decodes visual examples retaining 70% ground-truth tokens, so these images do not demonstrate autonomous future-image synthesis. No benchmark was executed.')
upd('sc2wm',pages='1-8,13-18',associated=['SC2-WM (arXiv).pdf: all 18 pages compared at the extracted-token level. Only the first-page arXiv stamp differs from the main PDF; method, tables and supplement text are identical.'],
 access='Both supplied 18-page versions include the same substantive supplement. Appendix pp. 15–16 explicitly defines delayed forecast-to-real-observation alignment (FRL); Table 6 gives SR 49.86 without adaptation, 49.48 for entropy minimization, 50.19 asynchronous and 50.90 FRL. Reported runtime rises from 17.78 to 18.92 seconds. Pages 17–18 report 500 physical robot runs (100 trials for each of five configurations), a 1.5 m success criterion and offboard/asynchronous processing; these are author experiments, not reproduced. The immediate endogenous delta is not the same quantity as this delayed residual. Source discrepancies are recorded in the implementation audit.')
records['sc2wm']['bottleneck']+=' The supplement and released code resolve the broad feedback concern: a delayed comparison with actual observations does exist. Remaining uncertainty concerns which parameters/trigger are used, prediction-target alignment and confidence under shift, not the absence of observed residual correction.'
for k,pages in [('cotvla','1,3-8'),('visualimaginations','1,3-7'),('hnr','1-8'),('navmorph','1,3-8'),('navq','1,3-8'),('sali','1,3-7')]:records[k]['pages']=pages
records['cotvla']['results']+=' Table 3, p. 8 tests two novel tasks with five trials each: generated goal images yield 20%/0% success, while demonstration goal images yield 60%/40%. This small privileged-goal intervention supports a subgoal-quality bottleneck. Section 5 reports approximately sevenfold inference slowdown at chunk length ten due to generating 256 visual tokens, and acknowledges missing high-frequency feedback between chunk boundaries.'
records['visualimaginations']['results']+=' Table 3, p. 6: removing imaginations at test time still gives SR 66.92 versus baseline 66.24, while correct imaginations give 67.26 and wrong ones 66.24. This directly supports a training regularization component plus a smaller aligned-input benefit. Table 6, p. 7 compares no auxiliary loss (66.75 SR), InfoNCE (67.18) and cosine alignment (67.26); the loss choice has modest effects. Selected attention visualizations explicitly do not establish causality.'
records['hnr']['results']+=' Table 5, p. 8 reports rendering at 11.5 ms on one RTX 3090, versus 169.5 ms without sparse sampling and 42.3 ms without KD-tree search. This is component timing. Table 6 gives SR 60.74 for soft supervision versus 56.72 for the hard-target variant; the authors attribute the latter to occlusion and prediction noise.'
records['navmorph']['results']+=' Table 3, p. 8: removing reconstruction/action/KL yields SR 45.51/44.81/44.10 versus 47.91 full; without self-evolution it is 45.08. Table 4 gives 21.22 seconds per instruction for contextual memory versus 44.56 for the LSTM adaptation variant. Memory size 1000 gives the best SR in Figure 4, while both smaller and larger settings can hurt. The authors explicitly acknowledge cross-episode test-scene memory and evaluation-fairness concerns.'
records['navq']['results']+=' Table 4, p. 8: gamma 0/0.3/0.5/0.7 gives SR 51.12/51.95/53.22/50.89. Longer successor aggregation is useful only up to a point in this experiment. The source constructs targets on one stored shortest-path tree, not all equal shortest paths.'
upd('wmnav',venue='IROS 2025; author project labels Oral',source='https://b0b8k1ng.github.io/WMNav/')
records['wmnav']['bottleneck']='DEDUCTION: ordinary minimum merging prevents recovery from a falsely low exploration value when a later estimate rises. However, the released code explicitly resets identified goal-mask cells to 10, so this is a scoped limitation with a recovery exception. Prompt scores are not calibrated probabilities. The printed 1.0 versus 0.1 m stopping threshold is inconsistent, and the inspected code uses 0.8 m internally; exact configuration must be stated.'
records['eoe']['bottleneck']=records['eoe']['bottleneck'].replace('exact-string','lexical')+' The ImageNet20 near-OOD setting additionally filters semantic cosine overlap at 0.85; the limitation is incomplete unknown-class coverage, not a total absence of semantic filtering.'
# Readability cleanup for numeric adjacency and the remaining compact draft phrases.
fix={'a3D':'a 3D','a4-layer':'a four-layer','a3-layer':'a three-layer','TwoMLPs':'Two MLPs','aCVAE':'a CVAE','frozenLLM':'frozen LLM','HNR-panoramic':'HNR panoramic','a second':'a second','np atches':'n patches','sixview':'six-view','selfgenerated':'self-generated','modelsize':'model size','notbestSPL':'not the best SPL','notR2R':'not R2R','actionlessEgo4Dtime':'actionless Ego4D time','robotstep':'robot step','lookupdictionary':'lookup dictionary','one-stepnavigation':'one-step navigation','semanticmIoU':'semantic mIoU','navigationSR':'navigation SR','pretraineddVAE':'pretrained dVAE','cachedCLIPfeatures':'cached CLIP features','MLP align':'MLP align','high-resolutionSACSoN/HuRoN':'high-resolution SACSoN/HuRoN','LPIPStime-only':'LPIPS for time-only','ImageNetFPR':'ImageNet FPR','NoMaDproposals':'NoMaD proposals','StreetView/BehaviorVisionSuite':'Street View/Behavior Vision Suite','sixpanoramicRGB':'six panoramic RGB','SixpanoramicRGB':'Six panoramic RGB','ObjectNavdemonstrations':'ObjectNav demonstrations','learnedwaypoints':'learned waypoints','oracleviews':'oracle views','NVSdomainshift':'NVS domain shift','pretrainedVERPointNav':'pretrained VER PointNav','trainingfree':'training-free','selectivefoveation/memory':'selective foveation/memory','futurecaption':'future caption','PanoramicRGB':'Panoramic RGB','GaussianSplat':'Gaussian Splat','detectorconfidence':'detector confidence','action-changeL1':'action-change L1','backgroundshift':'background shift','rewarddetector':'reward detector','VLMproposal':'VLM proposal','feature/dynamics':'feature/dynamics','tabletop/robot':'tabletop/robot','dot(expert,predicted)':'dot(expert, predicted)','planKL/language':'plan KL/language','active-UCB':'active UCB','unknown/occupied/free':'unknown/occupied/free','target-channel':'target-channel','ImageNet20':'ImageNet20','goal-approaching':'goal-approaching','actorcritic':'actor–critic','datasetstep':'dataset step','fromDREAMWALKER':'from DREAMWALKER','andFantasyVLN':'and FantasyVLN','andWorldVLN':'and WorldVLN','versusNoMaD':'versus NoMaD','versusNWM':'versus NWM','fullSR':'full SR','finegrained':'fine-grained','CLIPN':'CLIPN','Noalignment':'No alignment','dynamicvocabulary':'dynamic vocabulary','latentARvideo':'latent autoregressive video'}
for n in records.values():
 for key in ['problem','mechanism','novelty','results','bottleneck','followups','access']:
  if key not in n:continue
  s=n[key]
  for a,b in fix.items():s=s.replace(a,b)
  # Preserve scientific identifiers and URLs while separating prose/numbers.
  s=re.sub(r'(?<=[a-z])(?=\d)', ' ',s)
  s=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',s)
  s=re.sub(r'(?<=[A-Za-z])(?=\()',' ',s)
  s=re.sub(r'(?<=\))(?=[A-Za-z])',' ',s)
  for model in ['R2R','R4R','R2R-CE','GPT4o','ResNet152','ResNet18','CLIP','DINOv2','VILA-U7B','Qwen2','Qwen2.5','D4PG','3D','RGB-D']:
   spaced=re.sub(r'(?<=[a-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',model)
   s=s.replace(spaced,model)
  n[key]=s
for f in files:
 data={k:v for k,v in records.items() if owners[k]==f}
 f.write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print('Revised',len(records),'paper notes')
